(()=>{
const B=window.FT_LAB_BRIDGE,doc=document,qs=s=>doc.querySelector(s),all=s=>[...doc.querySelectorAll(s)];
let mode='orbit',g=null,menu=null,suppress=null,revision=0,scheduled=false;
const en=doc.documentElement.lang==='en',L=(a,b)=>en?b:a;
const style=doc.createElement('style');style.textContent=`
.qa-fab{display:none!important}[data-author-picker]:not([data-fixed-author]){display:none!important}
body:not(.lab-mode-orbit) .lab-surface{position:relative!important}.lab-mark{position:absolute;right:3px;top:2px;font-size:8px;line-height:12px;font-weight:700;letter-spacing:-.2px;white-space:nowrap;opacity:.65;pointer-events:none}.lab-mark.active{opacity:1}.act .lab-mark{top:auto;bottom:3px;right:50%;transform:translateX(50%);font-size:8px;line-height:10px}.post-a .lab-mark,.r-acts .lab-mark{top:0;right:0;font-size:6px;line-height:7px}.lab-mode-split .lab-mark{pointer-events:auto;background:var(--surf);color:var(--ink);border:1px solid var(--line);padding:0 3px;border-radius:5px;min-height:15px;min-width:24px;font-size:8px}.lab-mode-dual .lab-mark{pointer-events:auto;display:flex;gap:2px;background:var(--surf);color:var(--ink);border-radius:5px}.lab-dual{padding:1px 3px;border-radius:4px;line-height:13px;min-width:16px}.lab-dual.on{background:var(--accent-soft);color:var(--accent)}:is(.lab-mode-gesture,.lab-mode-orbit) .lab-surface{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;touch-action:pan-y}.lab-hold{box-shadow:inset 0 0 0 2px var(--violet)!important}
#lab-choice,#lab-gesture{position:fixed;z-index:999;width:228px;max-width:calc(100vw - 24px);padding:6px;border:1px solid var(--line2);border-radius:17px;background:var(--surf);color:var(--ink);box-shadow:0 12px 40px #0004;font:12px/1.45 var(--font)}#lab-gesture{pointer-events:none}#lab-choice button{display:flex;width:100%;justify-content:space-between;align-items:center;padding:12px 10px;border-radius:11px;min-height:47px}#lab-choice button:hover{background:var(--raise)}.lab-option{padding:10px;border-radius:11px;display:flex;align-items:center;gap:8px;font-size:12px}.lab-option b{font-size:13px}.lab-option small{display:block;font-size:10px;color:var(--mute)}.lab-option.selected{background:var(--accent-soft);color:var(--accent)}.lab-option .lab-arrow{font-size:18px;width:20px}.lab-center{font-size:9px;color:var(--mute);text-align:center;padding:7px}.lab-foot{font-size:9px;color:var(--mute);padding:7px 9px;border-top:1px solid var(--line)}#lab-hit{position:fixed;inset:0;z-index:998;background:#0001}

.lab-mode-orbit .lab-hold{box-shadow:0 0 0 3px var(--surf),0 0 0 7px #d9084838!important}
#lab-gesture.lab-orbit{width:244px;height:212px;padding:0;border:0;background:transparent;box-shadow:none;font:14px/1.35 var(--font)}
.lab-orbit .orbit-pill{position:absolute;display:flex;align-items:center;justify-content:center;gap:7px;min-height:42px;padding:10px 14px;border-radius:24px;background:var(--surf);color:var(--ink);box-shadow:0 3px 18px #0002;border:1px solid var(--line);font-size:13px;font-weight:600;white-space:nowrap;transition:background .12s,color .12s,transform .12s}
.lab-orbit .orbit-pill.selected{background:var(--accent);color:white;border-color:var(--accent);transform:scale(1.04)}
.orbit-pill[data-who=couple]{left:25px;top:0}.orbit-pill[data-who=me]{left:25px;top:104px}.orbit-pill[data-who=both]{left:116px;top:52px}
.orbit-dot{position:absolute;left:65px;top:62px;width:22px;height:22px;border:7px solid var(--surf);background:var(--faint);border-radius:50%;box-shadow:0 2px 12px #0002}
.orbit-caption{position:absolute;top:160px;left:0;width:244px;border:1px solid var(--line);border-radius:14px;padding:10px 12px;background:var(--surf);color:var(--ink);text-align:center;box-shadow:0 3px 18px #0002;font-size:12px;font-weight:650}.orbit-caption small{display:block;font-size:11px;font-weight:400;color:var(--mute);margin-top:3px}
@media(prefers-reduced-motion:reduce){.lab-orbit .orbit-pill{transition:none}}
`;doc.head.append(style);
function states(b){return{me:B.state(b,'me'),couple:B.isPair()&&B.state(b,'couple')};}
function tapWho(b){const s=states(b),i=B.info(b);return i.both&&s.me&&s.couple?'both':i.both&&s.me?'me':i.both&&s.couple?'couple':B.current();}
function next(b,who){const i=B.info(b),s=states(b),on=who==='both'?s.me&&s.couple:s[who];return on&&i.type==='like'?L('Убрать лайк','Remove like'):on&&i.type==='follow'?L('Отписаться','Unfollow'):i.title;}
function short(who){return who==='both'?L('Я + Мы','Me + Us'):who==='couple'?L('Мы','Us'):L('Я','Me');}
function eligible(b){return B.isPair()&&B.eligible(b)&&!b.disabled&&!b.closest('#lab-choice,#lab-gesture');}
function decorate(){scheduled=false;if(!B.isPair())return;if(mode==='orbit')B.personalIdle();all('#main button[data-act]').filter(eligible).forEach(b=>{const i=B.info(b),s=states(b),stamp=[revision,i.key,s.me,s.couple,B.current()].join('|');if(b.dataset.labStamp===stamp&&(mode==='orbit'||b.querySelector('.lab-mark')))return;b.querySelector('.lab-mark')?.remove();b.classList.add('lab-surface');b.dataset.labStamp=stamp;if(mode==='orbit')return;const mark=doc.createElement('span');mark.className='lab-mark'+(s.me||s.couple?' active':'');mark.setAttribute('aria-hidden','true');if(mode==='dual'){for(const who of ['me','couple']){const t=doc.createElement('span');t.className='lab-dual'+(s[who]?' on':'');t.dataset.labWho=who;t.textContent=short(who);mark.append(t);}}else mark.textContent=short(mode==='gesture'?tapWho(b):B.current())+(mode==='split'?'⌄':'');b.append(mark);});}
function schedule(){if(!scheduled){scheduled=true;requestAnimationFrame(decorate);}}
new MutationObserver(schedule).observe(qs('#main'),{subtree:true,childList:true});
new MutationObserver(schedule).observe(qs('#sheet'),{attributes:true,attributeFilter:['class'],childList:true});
new MutationObserver(schedule).observe(qs('#matchLayer'),{childList:true});
function place(el,b){const r=b.getBoundingClientRect();el.style.left=Math.max(12,Math.min(r.left+r.width/2-el.offsetWidth/2,innerWidth-el.offsetWidth-12))+'px';el.style.top=Math.max(12,Math.min(r.top+r.height/2-el.offsetHeight/2,innerHeight-el.offsetHeight-12))+'px';}
function closeMenu(){qs('#lab-choice')?.remove();qs('#lab-hit')?.remove();menu=null;}
function showMenu(b){closeMenu();menu={b,immediate:mode==='choose'};const shade=doc.createElement('div');shade.id='lab-hit';shade.onclick=closeMenu;const el=doc.createElement('div');el.id='lab-choice';el.setAttribute('role','dialog');el.setAttribute('aria-label',L('От чьего имени','Choose identity'));el.setAttribute('aria-modal','true');for(const who of ['me','couple',...(B.info(b).both&&mode==='choose'?['both']:[])]){const row=doc.createElement('button');row.textContent=short(who)+' · '+(menu.immediate?next(b,who):who==='me'?L('Личный профиль','Personal profile'):L('Профиль пары','Couple profile'));row.onclick=()=>{const immediate=menu.immediate;closeMenu();if(immediate)commit(b,who);else{B.choose(who);revision++;decorate();}};el.append(row);}const foot=doc.createElement('div');foot.className='lab-foot';foot.textContent=menu.immediate?L('Выбор выполнит действие','Choosing performs the action'):L('Выбор меняет автора','Choosing changes the identity');el.append(foot);doc.body.append(shade,el);place(el,b);el.querySelector('button').focus({preventScroll:true});}
function commit(b,who){B.invoke(b,who);revision++;schedule();}
function blocked(b){return suppress&&Date.now()<suppress.until&&B.info(b).key===suppress.key;}
function block(b){suppress={key:B.info(b).key,until:Date.now()+650};}
function cancel(){if(!g)return;clearTimeout(g.timer);g.b.classList.remove('lab-hold');if(g.armed)block(g.b);g=null;qs('#lab-gesture')?.remove();}
function paintOrbit(){
 let el=qs('#lab-gesture');if(!el){el=doc.createElement('div');el.id='lab-gesture';el.className='lab-orbit';el.setAttribute('role','status');el.setAttribute('aria-live','polite');doc.body.append(el);}
 el.replaceChildren();
 for(const [who,arrow,text]of [['couple','↑',L('От пары','As couple')],['both','→',L('От обоих','As both')],['me','↓',L('От себя','As me')]]){if(who==='both'&&!B.info(g.b).both)continue;const pill=doc.createElement('div');pill.className='orbit-pill'+(g.who===who?' selected':'');pill.dataset.who=who;pill.textContent=arrow+' '+text;el.append(pill);}
 const dot=doc.createElement('span');dot.className='orbit-dot';el.append(dot);
 const caption=doc.createElement('div');caption.className='orbit-caption';caption.textContent=g.who?next(g.b,g.who)+' · '+(g.who==='both'?L('от обоих','as both'):g.who==='couple'?L('от пары','as couple'):L('от себя','as me')):L('Выбери, от чьего имени','Choose an identity');const hint=doc.createElement('small');hint.textContent=g.who?L('Отпусти — выполнить','Release to confirm'):L('В центре — отмена','Center cancels');caption.append(hint);el.append(caption);
 const r=g.b.getBoundingClientRect(),margin=12,w=244,h=212;
 el.style.left=Math.max(margin,Math.min(r.left+r.width/2-76,innerWidth-w-margin))+'px';
 const above=r.top-h-18,below=r.bottom+18;el.style.top=Math.max(margin,Math.min(above>=margin?above:below+h<innerHeight-margin?below:r.top+r.height/2-h/2,innerHeight-h-margin))+'px';
}
function paint(){if(!g?.armed)return;if(mode==='orbit'){paintOrbit();return;}let el=qs('#lab-gesture');if(!el){el=doc.createElement('div');el.id='lab-gesture';el.setAttribute('role','status');el.setAttribute('aria-live','polite');doc.body.append(el);}el.replaceChildren();for(const [who,arrow]of [['couple','↑'],['both','→'],['me','↓']]){if(who==='both'&&!B.info(g.b).both)continue;const row=doc.createElement('div');row.className='lab-option'+(g.who===who?' selected':'');const a=doc.createElement('span');a.className='lab-arrow';a.textContent=arrow;const t=doc.createElement('span');const title=doc.createElement('b');title.textContent=short(who);const action=doc.createElement('small');action.textContent=next(g.b,who);t.append(title,action);row.append(a,t);el.append(row);}const hint=doc.createElement('div');hint.className='lab-center';hint.textContent=g.who?L('Отпусти — выполнить','Release to confirm'):L('Центр — отмена','Center — cancel');el.append(hint);place(el,g.b);}
function arm(){if(!g||!g.b.isConnected){cancel();return;}g.armed=true;g.b.classList.add('lab-hold');paint();}
function start(b,x,y,kind,token){cancel();if(!eligible(b)||!['gesture','orbit'].includes(mode))return;suppress=null;g={b,x,y,kind,token,who:null,armed:false,timer:setTimeout(arm,280)};}
function move(x,y){if(!g)return;const dx=x-g.x,dy=y-g.y;if(!g.armed){if(Math.hypot(dx,dy)>9){block(g.b);cancel();}return;}g.who=dx>35&&dx>Math.abs(dy)*1.15&&B.info(g.b).both?'both':Math.abs(dx)>85?null:dy<-32?'couple':dy>32?'me':null;paint();}
function finish(){if(!g)return false;const{b,who,armed}=g;cancel();if(armed){block(b);if(who)commit(b,who);}return armed;}
doc.addEventListener('click',e=>{const b=e.target.closest('button[data-act]');if(!b||!eligible(b))return;if(blocked(b)){e.preventDefault();e.stopImmediatePropagation();return;}e.preventDefault();e.stopImmediatePropagation();if(mode==='choose'||mode==='split'&&e.target.closest('.lab-mark'))showMenu(b);else if(mode==='dual'){const w=e.target.closest('[data-lab-who]')?.dataset.labWho;if(w)commit(b,w);else showMenu(b);}else commit(b,mode==='orbit'?'me':mode==='gesture'?tapWho(b):B.current());},true);
doc.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button!==0)return;const b=e.target.closest('.lab-surface');if(b){start(b,e.clientX,e.clientY,'pointer',e.pointerId);if(g)b.setPointerCapture(e.pointerId);}},true);
doc.addEventListener('pointermove',e=>{if(g?.kind==='pointer'&&g.token===e.pointerId)move(e.clientX,e.clientY);});doc.addEventListener('pointerup',e=>{if(g?.kind==='pointer'&&g.token===e.pointerId)finish();});doc.addEventListener('pointercancel',e=>{if(g?.kind==='pointer'&&g.token===e.pointerId)cancel();});
doc.addEventListener('touchstart',e=>{if(e.touches.length!==1){cancel();return;}const b=e.target.closest('.lab-surface');if(b){const t=e.touches[0];start(b,t.clientX,t.clientY,'touch',t.identifier);}},{passive:true});doc.addEventListener('touchmove',e=>{if(g?.kind!=='touch')return;const t=[...e.touches].find(t=>t.identifier===g.token);if(!t){cancel();return;}if(g.armed)e.preventDefault();move(t.clientX,t.clientY);},{passive:false});doc.addEventListener('touchend',e=>{if(g?.kind==='touch'&&[...e.changedTouches].some(t=>t.identifier===g.token)){if(g.armed)e.preventDefault();finish();}},{passive:false});doc.addEventListener('touchcancel',cancel);
doc.addEventListener('contextmenu',e=>{if(g?.armed&&e.target.closest('.lab-surface'))e.preventDefault();});
doc.addEventListener('keydown',e=>{const b=e.target.closest('.lab-surface');if(['gesture','orbit'].includes(mode)&&b&&eligible(b)&&['ArrowUp','ArrowDown','ArrowRight'].includes(e.key)){if(e.key==='ArrowRight'&&!B.info(b).both)return;e.preventDefault();e.stopImmediatePropagation();if(g?.b!==b){start(b,0,0,'keyboard',null);clearTimeout(g.timer);arm();}g.who=e.key==='ArrowUp'?'couple':e.key==='ArrowDown'?'me':'both';paint();return;}if(g?.kind==='keyboard'&&['Enter',' ','Escape','Tab'].includes(e.key)){if(e.key==='Tab'){cancel();return;}e.preventDefault();e.stopImmediatePropagation();e.key==='Escape'?cancel():finish();return;}if(menu){if(e.key==='Escape'){e.preventDefault();closeMenu();}else if(e.key==='Tab'){const items=[...qs('#lab-choice').querySelectorAll('button')],i=items.indexOf(doc.activeElement);if(!e.shiftKey&&i===items.length-1){e.preventDefault();items[0].focus();}else if(e.shiftKey&&i===0){e.preventDefault();items.at(-1).focus();}}}},true);
doc.addEventListener('scroll',cancel,{capture:true,passive:true});window.addEventListener('blur',cancel);window.addEventListener('resize',()=>{cancel();closeMenu();});
window.FT_REAL_ACTION_LAB={setMode(v){cancel();closeMenu();mode=v;revision++;doc.body.classList.remove('lab-mode-split','lab-mode-choose','lab-mode-dual','lab-mode-gesture','lab-mode-orbit');doc.body.classList.add('lab-mode-'+mode);decorate();}};
decorate();
})();
